import base64,datetime,hashlib,json,os,pathlib,socket,subprocess,tempfile
FILES={'.gitattributes': 'KiB0ZXh0IGVvbD1sZgo=', '.gitignore': 'X19weWNhY2hlX18vCioucHljCg==', 'README.md': '', 'SHA256SUMS': '', 'backup-inner.sh': '', 'backup.sh': '', 'checks.py': '', 'common.sh': '', 'probe.sh': '', 'tests/fake_kubectl.py': '', 'tests/test_backup_inner.py': '', 'tests/test_checks.py': '', 'tests/test_integration.py': '', 'tests/test_lifecycle.py': ''}
assert os.geteuid()==0 and socket.gethostname().split('.')[0]=='k8s-control01'
os.umask(0o077)
root=pathlib.Path(tempfile.mkdtemp(prefix='sec01-probe-20261008-',dir='/root'))
code=root/'source';code.mkdir()
for name,payload in FILES.items():
 f=code/name;f.parent.mkdir(parents=True,exist_ok=True);f.write_bytes(base64.b64decode(payload))
args=['sha256sum','-c','SHA256SUMS'];q=subprocess.run(args,cwd=code,capture_output=True,timeout=10)
