result={'root':str(root),'host':socket.gethostname(),'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_commit':'d6866187ae32af286cd5d9c651cdcb4d706f5f59','hash_rc':q.returncode,'hash_stdout':q.stdout.decode(),'code_files':{n:hashlib.sha256((code/n).read_bytes()).hexdigest() for n in FILES}}
(root/'stage.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result));assert q.returncode==0
